<script setup lang="ts">import { ref } from 'vue'; const props=defineProps<{token:string;slug:string;hostname?:string}>(); const emit=defineEmits<{close:[]}>(); const copied=ref(false); async function copy(value:string){await navigator.clipboard.writeText(value);copied.value=true;}function unifi(){return `服務: 自訂\n主機名稱: ${props.hostname??'<RECORD_NAME>'}\n使用者名稱: ${props.slug}\n密碼: ${props.token}\n伺服器: ddns.example.com/api/compat/unifi/${props.slug}?hostname=`;}</script>
<template><div class="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4" role="dialog" aria-modal="true" aria-labelledby="token-title"><div class="card max-w-2xl"><h2 id="token-title" class="text-xl font-bold">請立即保存 Token</h2><p class="my-3 text-amber-300">關閉後無法再次取得明文；本頁不會把它寫入任何瀏覽器儲存空間。</p><code class="block break-all rounded bg-slate-950 p-3">{{token}}</code><div class="mt-4 flex flex-wrap gap-2"><button class="btn-primary" @click="copy(token)">{{copied?'已複製':'複製 Token'}}</button><button class="btn-secondary" @click="copy(`curl -X POST https://ddns.example.com/api/ddns/${props.slug} -H 'Authorization: Bearer ${props.token}'`)">複製 curl</button><button class="btn-secondary" @click="copy(unifi())">複製 UniFi 設定</button><button class="btn-secondary" @click="emit('close')">我已安全保存</button></div></div></div></template>
